/**
 * DOCX extraction against a real Word file.
 *
 * The fixture is generated by python-docx, so it is a standard deflated ZIP — the shape the
 * previous implementation could not read. An uncompressed XML string would pass a regex test
 * and prove nothing about real documents.
 */
const { test } = require('node:test')
const assert = require('node:assert/strict')
const fs = require('node:fs')
const os = require('node:os')
const path = require('node:path')
const zlib = require('node:zlib')
const { TaskStore } = require('../dist/main/tasks/store.js')
const { ProjectStore } = require('../dist/main/projects/store.js')
const { RequirementStore } = require('../dist/main/requirements/store.js')
const { AttachmentService, extractText, readZipEntry, documentXmlToText, decodeXmlEntities } = require('../dist/main/requirements/attachments.js')

const FIXTURE = path.join(__dirname, 'fixtures', 'sample.docx')
const DOCX = 'application/vnd.openxmlformats-officedocument.wordprocessingml.document'

function setup(t) {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'studio-docx-'))
  const store = new TaskStore(path.join(dir, 'studio.db'))
  t.after(() => store.close())
  const projects = new ProjectStore(store)
  projects.create({ id: 'proj-a', name: 'A', rootPath: fs.mkdtempSync(path.join(dir, 'root-')), engine: 'cocos-creator-3.8.6', platform: 'wechat-minigame' })
  return { dir, req: new RequirementStore(store.db), store }
}

test('the fixture is a real compressed DOCX', () => {
  assert.equal(fs.existsSync(FIXTURE), true, 'the fixture must exist')
  const bytes = fs.readFileSync(FIXTURE)
  assert.equal(bytes.subarray(0, 2).toString('latin1'), 'PK', 'a DOCX is a ZIP')
  // The central directory entry for the document must be deflated, not stored: that is what
  // the old regex-based reader could not handle.
  const xml = readZipEntry(bytes, 'word/document.xml')
  assert.ok(xml && xml.length > 0, 'word/document.xml must be readable')
  assert.match(xml, /<w:document/, 'the entry must be the real document XML')
})

test('the old approach would not have worked', () => {
  const bytes = fs.readFileSync(FIXTURE)
  // Reading the ZIP as UTF-8 and looking for <w:t> finds nothing, because the payload is
  // deflated. This pins the reason the fix was needed.
  const naive = bytes.toString('utf8')
  assert.equal(/<w:t[^>]*>/.test(naive), false, 'raw bytes must not contain readable runs')
})

test('the fixture text is extracted', () => {
  const bytes = fs.readFileSync(FIXTURE)
  const result = extractText(bytes, DOCX)
  assert.ok(result.text, 'extraction must succeed: ' + result.note)
  assert.match(result.text, /自动攻击/)
  assert.match(result.text, /微信小游戏/)
  assert.match(result.text, /每 30 秒一波/)
  assert.match(result.note, /样式、图片与表格排版丢失/)
})

test('paragraph breaks survive extraction', () => {
  const bytes = fs.readFileSync(FIXTURE)
  const text = extractText(bytes, DOCX).text
  assert.match(text, /GDD 摘要/, 'the heading text must be present')
  assert.ok(text.split('\n').length >= 3, 'paragraphs must still be separate lines')
})

test('XML entities are decoded', () => {
  const bytes = fs.readFileSync(FIXTURE)
  const text = extractText(bytes, DOCX).text
  assert.match(text, /A & B < C > D/, 'entities must decode to their characters: ' + text.slice(0, 200))
  assert.equal(text.includes('&amp;'), false, 'no raw entity may survive')
})

test('a file that is not a ZIP is refused', () => {
  const result = extractText(Buffer.from('this is not a docx'), DOCX)
  assert.equal(result.text, null)
  assert.match(result.note, /找不到 word\/document.xml/)
})

test('a ZIP without the document entry is refused', (t) => {
  // A real ZIP, but not a Word document. Deflated "hello" under an unrelated name.
  const payload = zlib.deflateRawSync(Buffer.from('hello'))
  const name = Buffer.from('other.txt')
  const zip = Buffer.alloc(30 + name.length + payload.length)
  zip.writeUInt32LE(0x04034b50, 0)
  zip.writeUInt16LE(20, 4)
  zip.writeUInt16LE(0, 6)
  zip.writeUInt16LE(8, 8)
  zip.writeUInt32LE(payload.length, 18)
  zip.writeUInt32LE(Buffer.byteLength('hello'), 22)
  zip.writeUInt16LE(name.length, 26)
  name.copy(zip, 30)
  payload.copy(zip, 30 + name.length)
  // No central directory: the reader must decline rather than throw.
  assert.equal(readZipEntry(zip, 'word/document.xml'), null)
})

test('an empty document is reported as empty, not as success', () => {
  const xml = '<?xml version="1.0"?><w:document><w:body><w:p></w:p></w:body></w:document>'
  assert.equal(documentXmlToText(xml), '')
})

test('entity decoding handles numeric forms', () => {
  assert.equal(decodeXmlEntities('&#65;&#x42;'), 'AB')
})

test('a real DOCX attachment is stored with its text and its hash', (t) => {
  const { dir, req } = setup(t)
  const service = new AttachmentService({ store: req, dataDir: path.join(dir, 'data') })
  const bytes = fs.readFileSync(FIXTURE)
  const result = service.add({ projectId: 'proj-a', filename: 'gdd.docx', mime: DOCX, buffer: bytes })
  assert.equal(result.ok, true, result.detail)
  assert.match(result.attachment.extractedText, /自动攻击/)
  assert.equal(result.attachment.bytes, bytes.length, 'the original bytes must be preserved')
  assert.equal(result.attachment.sha256.length, 64)
  assert.equal(fs.existsSync(result.attachment.storedPath), true, 'the original file must be kept on disk')
})
